def R(html, old, new, n=1, required=True):
    """replace с проверкой что якорь найден."""
    if old not in html:
        if required:
            raise SystemExit(f"[ANCHOR NOT FOUND]\n{old[:120]}")
        return html
    return html.replace(old, new, n)

